// Tiny audio manager. Plays /public/audio/*.mp3 if present; silent no-op if missing.
// Files are generated by scripts/generate-audio.mjs and live in public/audio/.
import type { Element as GameElement } from "./game/critters";

export type SfxName =
  | "hit"
  | "catch"
  | "encounter"
  | "levelup"
  | "hit-ember"
  | "hit-aqua"
  | "hit-leaf"
  | "hit-normal"
  | "ui-click"
  | "ui-confirm"
  | "ui-cancel"
  | "summon-shimmer";

const VOL: Record<SfxName, number> = {
  hit: 0.5,
  catch: 0.6,
  encounter: 0.5,
  levelup: 0.6,
  "hit-ember": 0.5,
  "hit-aqua": 0.5,
  "hit-leaf": 0.5,
  "hit-normal": 0.5,
  "ui-click": 0.35,
  "ui-confirm": 0.45,
  "ui-cancel": 0.4,
  "summon-shimmer": 0.55,
};

/** Element-specific hit sound for a move's element. */
export function hitSfxFor(element: GameElement): SfxName {
  switch (element) {
    case "Ember":
      return "hit-ember";
    case "Aqua":
      return "hit-aqua";
    case "Leaf":
      return "hit-leaf";
    default:
      return "hit-normal";
  }
}

export type MusicContext = "field" | "battle";

const MUSIC_SRC: Record<MusicContext, string> = {
  field: "/audio/bgm-town.m4a",
  battle: "/audio/bgm-battle.m4a",
};
/** The original single track, kept as the fallback if a themed loop is missing. */
const FALLBACK_MUSIC = "/audio/bgm.mp3";
const MUSIC_VOLUME = 0.32;

/** Ordered sources to try for a music context. */
export function musicSources(context: MusicContext): string[] {
  return [MUSIC_SRC[context], FALLBACK_MUSIC];
}

// small pool per sound so rapid repeats don't cut each other off
const pools: Partial<Record<SfxName, HTMLAudioElement[]>> = {};

function pool(name: SfxName): HTMLAudioElement[] {
  if (!pools[name]) {
    pools[name] = Array.from({ length: 3 }, () => {
      const a = new Audio(`/audio/${name}.mp3`);
      a.volume = VOL[name];
      a.preload = "auto";
      return a;
    });
  }
  return pools[name]!;
}

// Sound state: `started` flips on the first user gesture, `enabled` is the player's mute toggle.
let started = false;
let enabled = true;
let context: MusicContext = "field";
let music: HTMLAudioElement | null = null;

export function sfx(name: SfxName) {
  if (!enabled) return; // the Sound toggle mutes every effect, not just music
  const p = pool(name);
  const a = p.find((x) => x.paused || x.ended) ?? p[0];
  try {
    a.currentTime = 0;
    void a.play().catch(() => {});
  } catch {
    /* file missing or blocked: silent */
  }
}

export function uiSfx(name: "ui-click" | "ui-confirm" | "ui-cancel") {
  sfx(name);
}

function loadTrack(sources: string[]): HTMLAudioElement {
  let i = 0;
  const a = new Audio(sources[i]);
  a.loop = true;
  a.volume = MUSIC_VOLUME;
  a.addEventListener("error", () => {
    // themed loop missing: fall back to the next source and keep playing if we should be
    if (i + 1 >= sources.length) return;
    i += 1;
    a.src = sources[i];
    if (started && enabled && music === a) void a.play().catch(() => {});
  });
  return a;
}

/**
 * Gapless loop buffer: equal-power crossfade of the last `fadeSec` into the first `fadeSec`, then
 * drop the tail so the end flows straight into the start. Returns new channel arrays of length
 * `length - fade`. Pure, so it is unit-tested.
 */
export function crossfadeLoop(channels: Float32Array[], sampleRate: number, fadeSec: number): Float32Array[] {
  return channels.map((ch) => {
    const n = Math.min(Math.floor(fadeSec * sampleRate), Math.floor(ch.length / 2));
    const out = ch.slice(0, ch.length - n);
    for (let i = 0; i < n; i++) {
      const t = ((i + 0.5) / n) * (Math.PI / 2);
      out[i] = ch[i] * Math.sin(t) + ch[ch.length - n + i] * Math.cos(t);
    }
    return out;
  });
}

const LOOP_FADE_SEC = 3;
let audioCtx: AudioContext | null = null;
let webGain: GainNode | null = null;
let webSource: AudioBufferSourceNode | null = null;
/** Bumped by every play/pause/switch request; any async step holding an older value is stale. */
let playGen = 0;
const loopBuffers: Partial<Record<MusicContext, Promise<AudioBuffer>>> = {};

type AudioCtor = typeof AudioContext;
const audioCtor = (): AudioCtor | undefined =>
  (globalThis as { AudioContext?: AudioCtor; webkitAudioContext?: AudioCtor }).AudioContext ??
  (globalThis as { webkitAudioContext?: AudioCtor }).webkitAudioContext;

function loadLoop(ctx: AudioContext, c: MusicContext): Promise<AudioBuffer> {
  return (loopBuffers[c] ??= fetch(MUSIC_SRC[c])
    .then((r) => {
      if (!r.ok) throw new Error(`music ${r.status}`);
      return r.arrayBuffer();
    })
    .then((bytes) => ctx.decodeAudioData(bytes))
    .then((buf) => {
      const chans = Array.from({ length: buf.numberOfChannels }, (_, i) => buf.getChannelData(i));
      const looped = crossfadeLoop(chans, buf.sampleRate, LOOP_FADE_SEC);
      const out = ctx.createBuffer(looped.length, looped[0].length, buf.sampleRate);
      looped.forEach((d, i) => out.copyToChannel(d as Float32Array<ArrayBuffer>, i));
      return out;
    })
    .catch((e) => {
      delete loopBuffers[c]; // allow a retry later
      throw e;
    }));
}

function stopWeb() {
  const src = webSource;
  webSource = null;
  if (!src) return;
  try {
    src.stop();
  } catch {
    /* already stopped */
  }
  src.disconnect();
}

/** Creates the AudioContext (inside a gesture when possible) and keeps it wired to the gain node. */
function ensureCtx(): AudioContext | null {
  if (audioCtx) return audioCtx;
  const Ctor = audioCtor();
  if (!Ctor) return null;
  try {
    audioCtx = new Ctor();
  } catch {
    return null;
  }
  webGain = audioCtx.createGain();
  webGain.gain.value = MUSIC_VOLUME;
  webGain.connect(audioCtx.destination);
  // iOS can move a running context to "interrupted" (calls, Siri); a later gesture must resume it.
  audioCtx.addEventListener("statechange", () => {
    if (started && enabled && audioCtx && audioCtx.state !== "running") rearmGesture();
  });
  return audioCtx;
}

type PlayResult = "playing" | "stale" | "failed";

/** WebAudio looping playback, rechecking generation/mute/context after every await. */
async function playWeb(c: MusicContext, gen: number): Promise<PlayResult> {
  const ctx = ensureCtx();
  if (!ctx) return "failed";
  const current = () => gen === playGen && enabled && started && context === c;
  let buf: AudioBuffer;
  try {
    buf = await loadLoop(ctx, c);
  } catch {
    return current() ? "failed" : "stale";
  }
  if (!current()) return "stale";
  try {
    await ctx.resume(); // already requested synchronously in the gesture; this just waits for it
  } catch {
    return current() ? "failed" : "stale";
  }
  if (!current()) return "stale"; // superseded or muted while resume() was pending
  music?.pause(); // only one backend active
  stopWeb();
  const src = ctx.createBufferSource();
  src.buffer = buf;
  src.loop = true;
  src.connect(webGain!);
  src.start();
  webSource = src;
  return "playing";
}

/** Starts (or restarts) the track for the current context if sound is on. */
function playCurrent() {
  if (!started || !enabled) return;
  const gen = ++playGen;
  void playWeb(context, gen).then((result) => {
    if (result !== "failed" || gen !== playGen || !enabled) return; // stale or muted: do nothing
    // WebAudio unavailable or decode failed: plain HTMLAudio, which can fall back to bgm.mp3
    stopWeb();
    music = trackFor(context);
    void music.play().catch(() => rearmGesture()); // autoplay blocked: next gesture retries
  });
}

const tracks: Partial<Record<MusicContext, HTMLAudioElement>> = {};

function trackFor(ctx: MusicContext): HTMLAudioElement {
  return (tracks[ctx] ??= loadTrack(musicSources(ctx)));
}

function pauseAllMusic() {
  playGen++; // invalidates any in-flight load/resume
  stopWeb();
  music?.pause();
}

/** Stops every pooled effect that is currently sounding. */
function stopAllSfx() {
  for (const p of Object.values(pools)) {
    for (const a of p ?? []) {
      a.pause();
      a.currentTime = 0;
    }
  }
}

/** Must run synchronously inside a user gesture: resume() is only honoured there on iOS/Safari. */
export function startMusic() {
  started = true;
  const ctx = ensureCtx();
  if (ctx && enabled && ctx.state !== "running") void ctx.resume().catch(() => {});
  playCurrent();
}

/** Switch between the field and battle loops. Never starts music while muted or before a gesture. */
export function setMusicContext(next: MusicContext) {
  if (next === context) return;
  context = next;
  if (!started) return; // startMusic() hasn't run yet; it will pick up the context
  pauseAllMusic();
  if (music) music.currentTime = 0;
  playCurrent();
}

export function toggleMusic(): boolean {
  if (!started) {
    enabled = true;
    startMusic();
    return true;
  }
  enabled = !enabled;
  if (enabled) {
    const ctx = ensureCtx();
    if (ctx && ctx.state !== "running") void ctx.resume().catch(() => {});
    playCurrent();
  } else {
    pauseAllMusic();
    stopAllSfx();
  }
  return enabled;
}

// --- gesture unlock: listeners stay armed until audio is actually running ---
let gestureTarget: EventTarget | null = null;
let gestureArmed = false;
const GESTURES = ["pointerdown", "keydown", "touchend"] as const;

function onGesture() {
  if (!started) startMusic();
  else if (enabled) {
    const ctx = ensureCtx();
    if (ctx && ctx.state !== "running") void ctx.resume().catch(() => {}); // sync, inside the gesture
    if (!webSource && !(music && !music.paused)) playCurrent();
  }
  // Disarm only once the context is genuinely running (or the player muted); otherwise keep waiting.
  if (!enabled || audioCtx?.state === "running" || (music && !music.paused)) disarmGesture();
}

function disarmGesture() {
  if (!gestureTarget || !gestureArmed) return;
  for (const g of GESTURES) gestureTarget.removeEventListener(g, onGesture);
  gestureArmed = false;
}

function rearmGesture() {
  if (!gestureTarget || gestureArmed || !started || !enabled) return;
  for (const g of GESTURES) gestureTarget.addEventListener(g, onGesture);
  gestureArmed = true;
}

/** Arm the first-gesture music start; stays armed until playback is running and re-arms if the
 *  context is later suspended or interrupted. */
export function armMusicOnGesture(target: EventTarget = window) {
  gestureTarget = target;
  if (gestureArmed) return;
  for (const g of GESTURES) target.addEventListener(g, onGesture);
  gestureArmed = true;
}

/** Click/confirm/cancel sounds for every button, via one delegated listener. */
const CANCEL = ".summon-close, .io-close, .sw-cancel, .dex-close, .guide-close, .summon-discard, [data-act=leave]";
const CONFIRM = ".summon-go, .io-primary, .victory-btn, .starter, .shop-buy";
export function installUiSounds(root: Document = document) {
  root.addEventListener("click", (e) => {
    const btn = (e.target as Element | null)?.closest?.("button");
    if (!btn || (btn as HTMLButtonElement).disabled || btn.classList.contains("mute")) return;
    uiSfx(btn.matches(CANCEL) ? "ui-cancel" : btn.matches(CONFIRM) ? "ui-confirm" : "ui-click");
  });
}
